export function lateCharge(lateMin: number): number {
  const base = baseLateCharge(lateMin);
  if (base >= LATE_CAP_PENCE) return LATE_CAP_PENCE;
  const steps = base / LATE_STEP_PENCE;
  if (steps <= 4) return base;
  // Each step after the fourth costs double, so add one more step's price for each.
  return Math.min(LATE_CAP_PENCE, base + (steps - 4) * LATE_STEP_PENCE);
}

